export default "/* =================================================================\n * agent-ops.css — source of truth for com.ikenga.agent-ops pane CSS.\n *\n * WP-20 (atelier-parity conformance): extracted from four hand-escaped\n * CSS-in-JS template-literal files (dist/lib/agent-ops{,-runs,-form,-live}\n * -css.js) into this single real .css source. scripts/build.mjs regenerates\n * dist/lib/agent-ops-css.js from this file via JSON.stringify — do not edit\n * the generated file directly.\n *\n * CSS ships as a JS string, not a <link>/@import: WebKitGTK cannot load\n * subresources from the about:srcdoc iframe the shell mounts pkgs into, so\n * CSS rides the script path — app.js injects the generated module as an\n * inline <style> after tokens-css.js (tokens define --fg/--bg-base/--space-*\n * etc.; the rules below consume them). Four sections below, in the exact\n * order app.js previously injected them (main -> runs -> form -> live);\n * class prefixes: .ao-* (pane chrome/shared), .b-*/.rr-*/.rd-* (badges /\n * run-row / run-detail cells), .ao-form-* (job form), .ao-live-* (live tail).\n * ================================================================= */\n\n/* ============ PANE (main) — schedule view + shared chrome/badges/toasts ============ */\n/* Auto-derived from the D-01 mock (board-timeline-first.html) pane CSS; shell-chrome\n * rules (.shell, .actbar, .sidemenu, .chrome-tag, .pane-frame-note) stripped —\n * those are SHELL, not pkg. Token mapping: D-01 used inline hsl(...) literals\n * (the mock was standalone); this replaces them with @ikenga/tokens semantic\n * slots so the pkg follows the shell active theme (A/B/C x light/dark). */\n\n/* ============ PANE LAYOUT ============ */\n.ao-screen {\n  display: flex;\n  height: 100%;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.ao-panebar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 11px 18px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n.ao-panebar h1 {\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: -.01em;\n  margin: 0;\n}\n.ao-panebar .sub { font-size: 11px; color: var(--fg-muted); }\n.ao-spacer { flex: 1; }\n\n.ao-loading {\n  font-size: 11px; color: var(--fg-muted); font-family: var(--font-mono);\n  margin-right: 10px; opacity: .85; animation: ao-pulse 1.2s ease-in-out infinite;\n}\n@keyframes ao-pulse { 0%,100% { opacity: .4; } 50% { opacity: .9; } }\n\n.ao-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 11.5px;\n  color: var(--fg-muted);\n  padding: 4px 9px;\n  border: 1px solid var(--border);\n  border-radius: 99px;\n}\n.ao-pill.up .ao-dot { background: var(--systemic); box-shadow: 0 0 0 3px var(--systemic-soft); }\n.ao-pill.down { color: var(--danger); border-color: var(--danger); }\n.ao-pill.down .ao-dot { background: var(--danger); box-shadow: 0 0 0 3px var(--danger-soft); }\n\n.ao-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 99px;\n  background: var(--systemic);\n}\n\n/* daemon-down banner */\n.ao-downbanner {\n  display: none;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 18px;\n  background: var(--danger-soft);\n  color: var(--danger);\n  font-size: 12px;\n  border-bottom: 1px solid var(--danger);\n  flex-shrink: 0;\n}\n.ao-screen.is-down .ao-downbanner { display: flex; }\n.ao-screen.is-down .ao-pill.up { display: none; }\n.ao-screen.is-down .ao-pill.down { display: inline-flex; }\n.ao-screen.is-down .ao-btn.run { opacity: .4; pointer-events: none; }\n\n.ao-body {\n  padding: 8px 18px 18px;\n  overflow-y: auto;\n  flex: 1;\n  min-height: 0;\n}\n\n/* ============ KPI STRIP ============ */\n.ao-kpis {\n  display: flex;\n  gap: 10px;\n  padding: 12px 0 4px;\n}\n.ao-kpi {\n  flex: 1;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-soft);\n  border-radius: 9px;\n  padding: 9px 12px;\n}\n.ao-kpi .n {\n  font-size: 19px;\n  font-weight: 700;\n  letter-spacing: -.02em;\n}\n.ao-kpi .l {\n  font-size: 10.5px;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: .04em;\n  margin-top: 1px;\n}\n.ao-kpi.ok .n { color: var(--systemic); }\n.ao-kpi.warn .n { color: var(--achievement); }\n.ao-kpi.bad .n { color: var(--danger); }\n\n/* ============ SECTION HEADERS ============ */\n.ao-section-h {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  margin: 14px 0 8px;\n}\n.ao-section-h h2 {\n  font-size: 12px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--fg-muted);\n  margin: 0;\n  white-space: nowrap;\n}\n.ao-section-h .rule {\n  flex: 1;\n  height: 1px;\n  background: var(--border-soft);\n}\n.ao-section-h .meta {\n  font-size: 11px;\n  color: var(--fg-faint, var(--fg-muted));\n  white-space: nowrap;\n}\n\n/* ============ TIMELINE ============ */\n.ao-timeline {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-soft);\n  border-radius: 9px;\n  padding: 12px 16px 8px;\n  position: relative;\n}\n.ao-tl-axis {\n  display: flex;\n  justify-content: space-between;\n  font-size: 10.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono);\n  border-bottom: 1px dashed var(--border);\n  padding-bottom: 6px;\n  margin-bottom: 8px;\n}\n.ao-tl-axis .tz { color: var(--fg-muted); }\n.ao-tl-now {\n  position: absolute;\n  top: 52px;\n  bottom: 10px;\n  width: 2px;\n  background: var(--achievement);\n  left: 6%;\n  opacity: .7;\n}\n.ao-tl-now::after {\n  content: 'now';\n  position: absolute;\n  top: -12px;\n  left: -9px;\n  font-size: 9px;\n  color: var(--achievement);\n  font-family: var(--font-mono);\n}\n.ao-tl-row {\n  position: relative;\n  height: 28px;\n  display: flex;\n  align-items: center;\n  border-radius: 5px;\n}\n.ao-tl-row:hover { background: var(--bg-raised); }\n.ao-tl-label {\n  position: absolute;\n  left: 6px;\n  top: 6px;\n  font-size: 11px;\n  font-weight: 600;\n  width: 120px;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  cursor: pointer;\n  user-select: none;\n}\n.ao-tl-label .chev {\n  color: var(--fg-faint, var(--fg-muted));\n  font-size: 9px;\n  width: 9px;\n}\n.ao-tl-label .cnt {\n  font-size: 9.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono);\n  font-weight: 400;\n}\n.ao-tl-lane {\n  position: absolute;\n  left: 134px;\n  right: 8px;\n  top: 0;\n  bottom: 0;\n}\n.ao-tl-fire {\n  position: absolute;\n  top: 5px;\n  height: 18px;\n  border-radius: 5px;\n  display: flex;\n  align-items: center;\n  padding: 0 7px;\n  font-size: 10px;\n  font-weight: 600;\n  white-space: nowrap;\n  cursor: pointer;\n  color: var(--primary-fg);\n  transform: translateX(-50%);\n}\n.ao-tl-fire.soon { background: var(--primary); }\n.ao-tl-fire.later {\n  background: var(--bg-raised);\n  color: var(--fg-muted);\n  border: 1px solid var(--border);\n}\n.ao-tl-fire.warn {\n  background: var(--achievement-soft);\n  color: var(--achievement);\n  border: 1px solid var(--achievement);\n}\n.ao-tl-fire.cluster {\n  background: var(--bg-sunken);\n  border: 1px dashed var(--border);\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n}\n.ao-tl-fire.skip {\n  background: transparent;\n  border: 1px dashed var(--fg-faint, var(--fg-muted));\n  color: var(--fg-faint, var(--fg-muted));\n  text-decoration: line-through;\n}\n/* sub-lane (expandable) */\n.ao-tl-sub { display: none; }\n.ao-tl-sub.open { display: block; }\n.ao-tl-sub .ao-tl-label {\n  font-weight: 400;\n  color: var(--fg-muted);\n  padding-left: 18px;\n}\n\n/* ============ JOB TABLE ============ */\n.ao-table {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-soft);\n  border-radius: 9px;\n  overflow: hidden;\n}\n.ao-table thead th {\n  text-align: left;\n  font-size: 10.5px;\n  text-transform: uppercase;\n  letter-spacing: .05em;\n  color: var(--fg-faint, var(--fg-muted));\n  font-weight: 600;\n  padding: 9px 12px;\n  border-bottom: 1px solid var(--border);\n  background: var(--bg-sunken);\n  cursor: pointer;\n  white-space: nowrap;\n}\n.ao-table thead th .ar { opacity: .5; font-size: 9px; }\n.ao-table tbody td {\n  padding: 9px 12px;\n  border-bottom: 1px solid var(--border-soft);\n  vertical-align: middle;\n}\n.ao-table tbody tr:hover { background: var(--bg-raised); }\n.ao-table tbody tr.ext { opacity: .62; }\n\n/* group row (externally managed) */\n.ao-grp td {\n  background: var(--bg-sunken);\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--fg-faint, var(--fg-muted));\n  font-weight: 700;\n  padding: 6px 12px;\n}\n\n/* job id / namespace */\n.ao-jid { font-family: var(--font-mono); font-size: 12px; color: var(--fg); }\n.ao-jns { color: var(--fg-faint, var(--fg-muted)); }\n.ao-label { font-size: 11px; color: var(--fg-muted); }\n\n/* mode pill */\n.ao-mode {\n  font-size: 9px;\n  font-family: var(--font-mono);\n  padding: 1px 5px;\n  border-radius: 4px;\n  margin-left: 6px;\n  vertical-align: middle;\n}\n.ao-mode.agent { background: var(--primary-soft); color: var(--primary-fg); }\n.ao-mode.script { background: var(--systemic-soft); color: var(--systemic); }\n\n/* next fire / ago */\n.ao-next { font-family: var(--font-mono); font-size: 12px; }\n.ao-next .cd {\n  color: var(--primary-fg);\n  background: var(--primary-soft);\n  padding: 1px 6px;\n  border-radius: 4px;\n}\n.ao-ago { font-family: var(--font-mono); font-size: 11px; color: var(--fg-muted); }\n.ao-ago .dur { color: var(--fg-faint, var(--fg-muted)); }\n\n/* 24h cost */\n.ao-cost { font-family: var(--font-mono); font-size: 11px; color: var(--achievement); text-align: right; }\n.ao-cost.none { color: var(--fg-faint, var(--fg-muted)); }\n\n/* sparkline bars (G-15 — height = duration) */\n.ao-bars { display: flex; gap: 2px; align-items: flex-end; height: 22px; }\n.ao-bar { width: 5px; border-radius: 1px; background: var(--systemic); min-height: 2px; }\n.ao-bar.f { background: var(--danger); }\n.ao-bar.s { background: var(--achievement); }\n.ao-bar.n { background: var(--border); }\n.ao-emptybars { font-size: 10px; color: var(--fg-faint, var(--fg-muted)); font-style: italic; }\n\n/* health badge */\n.ao-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 11px;\n  font-weight: 600;\n  padding: 2px 8px;\n  border-radius: 99px;\n  white-space: nowrap;\n}\n.ao-badge .d { width: 6px; height: 6px; border-radius: 99px; }\n.b-ok  { background: var(--systemic-soft); color: var(--systemic); }\n.b-ok  .d { background: var(--systemic); }\n.b-fail { background: var(--danger-soft); color: var(--danger); }\n.b-fail .d { background: var(--danger); }\n.b-run  { background: var(--primary-soft); color: var(--primary-fg); }\n.b-run  .d { background: var(--achievement); animation: ao-pulse 1.3s infinite; }\n.b-ext  { background: var(--bg-raised); color: var(--fg-faint, var(--fg-muted)); border: 1px solid var(--border); }\n.b-ext  .d { background: var(--fg-faint, var(--fg-muted)); }\n.b-off  { background: transparent; color: var(--fg-faint, var(--fg-muted)); border: 1px dashed var(--border); }\n.b-off  .d { background: var(--fg-faint, var(--fg-muted)); }\n.b-pending { background: var(--bg-raised); color: var(--fg-muted); border: 1px solid var(--border); }\n.b-pending .d { background: var(--fg-faint, var(--fg-muted)); }\n@keyframes ao-pulse { 0%,100%{opacity:1} 50%{opacity:.35} }\n\n/* consecutive-error alert */\n.ao-alert {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 10px;\n  color: var(--danger);\n  font-weight: 700;\n  margin-top: 3px;\n}\n\n/* controls (hover-reveal) */\n.ao-ctrls {\n  display: flex;\n  gap: 6px;\n  justify-content: flex-end;\n  opacity: 0;\n  transition: opacity .12s;\n}\ntr:hover .ao-ctrls,\ntr:focus-within .ao-ctrls { opacity: 1; }\n\n/* external tag */\n.ao-ext-tag {\n  font-size: 9.5px;\n  font-family: var(--font-mono);\n  color: var(--fg-faint, var(--fg-muted));\n  border: 1px solid var(--border);\n  padding: 1px 5px;\n  border-radius: 4px;\n}\n\n/* toggle switch */\n.ao-tog {\n  width: 30px;\n  height: 17px;\n  border-radius: 99px;\n  background: var(--systemic);\n  position: relative;\n  cursor: pointer;\n  flex: 0 0 auto;\n  border: 0;\n}\n.ao-tog::after {\n  content: '';\n  position: absolute;\n  width: 13px;\n  height: 13px;\n  border-radius: 99px;\n  background: #fff;\n  top: 2px;\n  right: 2px;\n}\n.ao-tog.off { background: var(--border); }\n.ao-tog.off::after { right: auto; left: 2px; }\n\n/* ============ BUTTONS ============ */\n.ao-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  font-family: inherit;\n  font-weight: 600;\n  white-space: nowrap;\n  cursor: pointer;\n  border-radius: 6px;\n  border: 1px solid var(--border);\n  background: var(--bg-raised);\n  color: var(--fg);\n  transition: border-color .12s, color .12s, background .12s, opacity .12s;\n}\n.ao-btn:hover { border-color: var(--primary); color: var(--primary-fg); }\n.ao-btn:disabled { opacity: .4; pointer-events: none; }\n.ao-btn.sz-sm { height: 26px; padding: 0 8px; font-size: 11px; }\n.ao-btn.sz-md { height: 30px; padding: 0 12px; font-size: 12px; }\n.ao-btn.run {\n  background: var(--primary);\n  border-color: var(--primary);\n  color: var(--primary-fg);\n}\n.ao-btn.run:hover { opacity: .9; }\n.ao-btn.run.billable::after { content: ' $'; font-size: 9px; }\n\n/* ============ CONFIRM MODAL (G-13) ============ */\n.ao-scrim {\n  display: none;\n  position: fixed;\n  inset: 0;\n  background: rgba(0,0,0,.6);\n  place-items: center;\n  z-index: 40;\n}\n.ao-scrim.open { display: grid; }\n.ao-modal {\n  background: var(--bg-raised);\n  border: 1px solid var(--border);\n  border-radius: 9px;\n  box-shadow: var(--shadow-3);\n  width: 380px;\n  padding: 18px;\n}\n.ao-modal h3 { font-size: 14px; margin: 0 0 4px; }\n.ao-modal p { font-size: 12px; color: var(--fg-muted); margin: 0 0 12px; }\n.ao-modal .costline {\n  background: var(--bg-sunken);\n  border: 1px solid var(--border-soft);\n  border-radius: 6px;\n  padding: 9px 11px;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  display: flex;\n  justify-content: space-between;\n  margin-bottom: 14px;\n}\n.ao-modal .costline b { color: var(--achievement); }\n.ao-modal .row { display: flex; gap: 8px; justify-content: flex-end; }\n\n/* ============ LEGEND ============ */\n.ao-legend {\n  /* Sticky footer, Ngwa-style — pinned to the pane bottom, scroll rides under it.\n     Negative margins bleed it to the .ao-body edges (body padding 8px 18px 18px). */\n  position: sticky;\n  bottom: 0;\n  display: flex;\n  gap: 14px;\n  flex-wrap: wrap;\n  font-size: 10.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  margin: 10px -18px -18px;\n  padding: 9px 18px;\n  background: var(--bg-base);\n  border-top: 1px solid var(--border);\n  z-index: 2;\n}\n.ao-legend span { display: inline-flex; align-items: center; gap: 5px; }\n.ao-legend i {\n  width: 9px;\n  height: 9px;\n  border-radius: 2px;\n  display: inline-block;\n}\n\n/* ============ EMPTY / ERROR STATES ============ */\n.ao-empty-box {\n  margin: 1rem;\n  display: flex;\n  height: 128px;\n  align-items: center;\n  justify-content: center;\n  border-radius: 6px;\n  border: 1px dashed var(--border);\n  font-size: 13px;\n  color: var(--fg-muted);\n  text-align: center;\n  flex-direction: column;\n  gap: 6px;\n}\n.ao-empty-box .sub { font-size: 11px; color: var(--fg-faint, var(--fg-muted)); font-family: var(--font-mono); }\n.ao-error {\n  margin: 1rem;\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  border-radius: 6px;\n  border: 1px solid color-mix(in srgb, var(--danger) 50%, transparent);\n  background: color-mix(in srgb, var(--danger) 10%, transparent);\n  padding: 12px;\n  font-size: 13px;\n  color: var(--danger);\n}\n.ao-loading {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 1rem;\n  font-size: 13px;\n  color: var(--fg-muted);\n}\n\n/* ============ PLACEHOLDER VIEWS (WP-11 / WP-13) ============ */\n.ao-placeholder {\n  flex: 1;\n  display: grid;\n  place-items: center;\n  text-align: center;\n  padding: 2rem;\n  color: var(--fg-muted);\n}\n.ao-placeholder .label {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  letter-spacing: .06em;\n  text-transform: uppercase;\n  color: var(--fg-faint, var(--fg-muted));\n  margin-top: 8px;\n}\n\n/* ============ SPINNER ============ */\n.ao-spin { animation: ao-spin 1s linear infinite; }\n@keyframes ao-spin { to { transform: rotate(360deg); } }\n\n/* ============ FOCUS RINGS ============ */\n.ao-btn:focus-visible,\n.ao-tl-row:focus-visible,\n.ao-tog:focus-visible { outline: 2px solid var(--primary); outline-offset: -2px; }\n\n/* ============ TOAST (WP-12) ============ */\n.ao-toast {\n  position: fixed;\n  bottom: 20px;\n  left: 50%;\n  transform: translateX(-50%);\n  z-index: 50;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 14px;\n  border-radius: var(--r, 7px);\n  border: 1px solid var(--border);\n  background: var(--bg-raised);\n  font-size: 12px;\n  font-weight: 500;\n  box-shadow: var(--shadow-3, 0 4px 16px rgba(0,0,0,.18));\n  white-space: nowrap;\n  pointer-events: none;\n  animation: ao-toast-in .18s ease-out forwards;\n}\n.ao-toast.ok { border-color: var(--systemic); color: var(--systemic); }\n.ao-toast.err { border-color: var(--danger); color: var(--danger); background: var(--danger-soft, var(--bg-raised)); }\n@keyframes ao-toast-in {\n  from { opacity: 0; transform: translateX(-50%) translateY(6px); }\n  to   { opacity: 1; transform: translateX(-50%) translateY(0); }\n}\n\n/* ============ RUNS + FAILURES — runs-view.js / failures-view.js + shared RunDetail panel ============ */\n/* WP-11. Class naming: .ao-runs-* / .ao-fail-* / .ao-run-detail / .ao-run-row. */\n\n/* ============ RUNS VIEW ============ */\n.ao-runs-screen {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow: hidden;\n}\n\n.ao-runs-header {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 11px 18px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n.ao-runs-header h1 {\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: -.01em;\n  margin: 0;\n}\n.ao-runs-header .sub { font-size: 11px; color: var(--fg-muted); }\n\n.ao-runs-body {\n  display: flex;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n/* left list pane */\n.ao-runs-list {\n  flex: 0 0 380px;\n  overflow-y: auto;\n  border-right: 1px solid var(--border-soft);\n  min-width: 0;\n}\n\n/* expand panel (right side) */\n.ao-runs-detail-pane {\n  flex: 1;\n  overflow-y: auto;\n  min-width: 0;\n  padding: 16px 20px;\n}\n.ao-runs-detail-pane.empty {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--fg-muted);\n  font-size: 13px;\n}\n\n/* ============ RUN LIST ROW ============ */\n.ao-run-row {\n  display: grid;\n  grid-template-columns: 28px 1fr auto;\n  align-items: center;\n  gap: 0 10px;\n  padding: 9px 14px;\n  border-bottom: 1px solid var(--border-soft);\n  cursor: pointer;\n  transition: background .1s;\n}\n.ao-run-row:hover { background: var(--bg-raised); }\n.ao-run-row.selected { background: var(--primary-soft); }\n.ao-run-row.is-skipped { opacity: .55; }\n\n.ao-run-row .rr-badge-col {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.ao-run-row .rr-main {\n  min-width: 0;\n}\n.ao-run-row .rr-job {\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.ao-run-row .rr-job .rr-ns { color: var(--fg-faint, var(--fg-subtle)); }\n.ao-run-row .rr-meta {\n  font-size: 10.5px;\n  color: var(--fg-muted);\n  margin-top: 2px;\n  display: flex;\n  gap: 6px;\n  align-items: center;\n  flex-wrap: wrap;\n}\n.ao-run-row .rr-meta .sep { color: var(--border); }\n.ao-run-row .rr-cost {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--achievement);\n  text-align: right;\n  flex-shrink: 0;\n}\n.ao-run-row .rr-cost.none { color: var(--fg-faint, var(--fg-subtle)); }\n\n/* skipped row label */\n.ao-skip-label {\n  font-size: 10px;\n  font-family: var(--font-mono);\n  background: var(--bg-sunken);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 1px 5px;\n  color: var(--fg-faint, var(--fg-subtle));\n  text-decoration: line-through;\n}\n\n/* ============ RUN DETAIL PANEL ============ */\n.ao-run-detail {\n  min-width: 0;\n}\n.ao-run-detail .rd-title {\n  font-family: var(--font-mono);\n  font-size: 13px;\n  font-weight: 700;\n  margin: 0 0 4px;\n  color: var(--fg);\n  word-break: break-all;\n}\n.ao-run-detail .rd-subtitle {\n  font-size: 11px;\n  color: var(--fg-muted);\n  margin: 0 0 14px;\n}\n\n.ao-run-detail .rd-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px 16px;\n  margin-bottom: 14px;\n}\n.ao-run-detail .rd-cell {\n  background: var(--bg-sunken);\n  border: 1px solid var(--border-soft);\n  border-radius: 7px;\n  padding: 8px 10px;\n}\n.ao-run-detail .rd-cell .k {\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: .05em;\n  color: var(--fg-muted);\n  margin-bottom: 3px;\n}\n.ao-run-detail .rd-cell .v {\n  font-family: var(--font-mono);\n  font-size: 12px;\n  color: var(--fg);\n  word-break: break-all;\n}\n.ao-run-detail .rd-cell .v.cost { color: var(--achievement); }\n.ao-run-detail .rd-cell .v.ok { color: var(--systemic); }\n.ao-run-detail .rd-cell .v.fail { color: var(--danger); }\n.ao-run-detail .rd-cell .v.running { color: var(--achievement); }\n\n/* section within detail */\n.ao-run-detail .rd-section {\n  margin-top: 12px;\n}\n.ao-run-detail .rd-section-h {\n  font-size: 10.5px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--fg-muted);\n  margin-bottom: 5px;\n  padding-bottom: 3px;\n  border-bottom: 1px solid var(--border-soft);\n}\n\n/* pre block for summary / error */\n.ao-pre {\n  background: var(--bg-sunken);\n  border: 1px solid var(--border-soft);\n  border-radius: 6px;\n  padding: 10px 12px;\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  color: var(--fg);\n  white-space: pre-wrap;\n  word-break: break-all;\n  overflow-y: auto;\n  max-height: 220px;\n  line-height: 1.55;\n}\n.ao-pre.error {\n  color: var(--danger);\n  background: color-mix(in srgb, var(--danger) 6%, var(--bg-sunken));\n  border-color: color-mix(in srgb, var(--danger) 30%, transparent);\n}\n.ao-pre.empty {\n  color: var(--fg-muted);\n  font-style: italic;\n}\n\n/* token row */\n.ao-token-row {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin-top: 6px;\n}\n.ao-token-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-family: var(--font-mono);\n  font-size: 11px;\n  background: var(--bg-raised);\n  border: 1px solid var(--border-soft);\n  border-radius: 99px;\n  padding: 2px 8px;\n  color: var(--fg-muted);\n}\n.ao-token-chip .tck { color: var(--fg-faint, var(--fg-subtle)); font-size: 9.5px; }\n\n/* ============ FAILURES VIEW ============ */\n.ao-fail-screen {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow: hidden;\n}\n\n.ao-fail-header {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 11px 18px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n.ao-fail-header h1 {\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: -.01em;\n  margin: 0;\n}\n.ao-fail-header .sub { font-size: 11px; color: var(--fg-muted); }\n\n.ao-fail-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 10px 18px 18px;\n}\n\n/* alert cards */\n.ao-fail-cards {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 16px;\n}\n\n.ao-fail-card {\n  background: color-mix(in srgb, var(--danger) 7%, var(--bg-surface));\n  border: 1px solid color-mix(in srgb, var(--danger) 35%, transparent);\n  border-radius: 9px;\n  padding: 12px 14px;\n}\n.ao-fail-card .fc-top {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 6px;\n}\n.ao-fail-card .fc-job {\n  font-family: var(--font-mono);\n  font-size: 12.5px;\n  font-weight: 700;\n  color: var(--fg);\n  flex: 1;\n  min-width: 0;\n}\n.ao-fail-card .fc-job .fc-ns { color: var(--fg-faint, var(--fg-subtle)); }\n.ao-fail-card .fc-count {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 12px;\n  font-weight: 700;\n  color: var(--danger);\n  background: var(--danger-soft);\n  padding: 2px 9px;\n  border-radius: 99px;\n  white-space: nowrap;\n}\n.ao-fail-card .fc-label {\n  font-size: 11.5px;\n  color: var(--fg-muted);\n  margin-bottom: 6px;\n}\n.ao-fail-card .fc-error {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  color: var(--danger);\n  background: color-mix(in srgb, var(--danger) 10%, transparent);\n  border-radius: 5px;\n  padding: 5px 8px;\n  margin-bottom: 4px;\n  white-space: pre-wrap;\n  word-break: break-all;\n  max-height: 80px;\n  overflow-y: auto;\n}\n.ao-fail-card .fc-last {\n  font-size: 10.5px;\n  color: var(--fg-muted);\n  font-family: var(--font-mono);\n}\n\n/* ============ SHARED RUN LIST (Failures view uses same .ao-run-row) ============ */\n.ao-fail-runs-list {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-soft);\n  border-radius: 9px;\n  overflow: hidden;\n}\n\n/* ============ LOADING / EMPTY ============ */\n.ao-runs-loading,\n.ao-fail-loading {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 1.5rem 18px;\n  font-size: 13px;\n  color: var(--fg-muted);\n}\n.ao-runs-empty,\n.ao-fail-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 2.5rem 1rem;\n  font-size: 13px;\n  color: var(--fg-muted);\n  text-align: center;\n}\n.ao-runs-empty .sub,\n.ao-fail-empty .sub {\n  font-size: 11px;\n  font-family: var(--font-mono);\n  color: var(--fg-faint, var(--fg-subtle));\n}\n\n/* healthy-all state in Failures */\n.ao-fail-healthy {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 3rem 1rem;\n  text-align: center;\n}\n.ao-fail-healthy .msg {\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--systemic);\n}\n.ao-fail-healthy .sub {\n  font-size: 11.5px;\n  color: var(--fg-muted);\n}\n\n/* ============ JOB FORM MODAL — job-form.js (create/edit/delete) ============ */\n/* WP-14. Reuses .ao-scrim/.ao-modal (confirm-modal base); adds .ao-form-* rules. */\n\n/* ============ JOB FORM MODAL (WP-14) ============ */\n\n/* Wider modal for the form */\n.ao-modal.ao-form-modal {\n  width: 480px;\n  max-width: calc(100vw - 32px);\n  max-height: calc(100vh - 40px);\n  overflow-y: auto;\n}\n\n.ao-form-modal h3 {\n  font-size: 14px;\n  font-weight: 700;\n  margin: 0 0 14px;\n}\n\n/* Form row: label + input stacked */\n.ao-form-row {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin-bottom: 12px;\n}\n.ao-form-row label {\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: .05em;\n}\n.ao-form-row .ao-hint {\n  font-size: 10.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  margin-top: 2px;\n}\n\n/* Text / number inputs */\n.ao-input {\n  height: 32px;\n  padding: 0 10px;\n  background: var(--bg-sunken);\n  border: 1px solid var(--border);\n  border-radius: var(--r, 6px);\n  color: var(--fg);\n  font-size: 12.5px;\n  font-family: inherit;\n  width: 100%;\n  box-sizing: border-box;\n  outline: none;\n  transition: border-color .1s;\n}\n.ao-input:focus { border-color: var(--primary); }\n.ao-input:disabled {\n  opacity: .55;\n  cursor: not-allowed;\n  background: var(--bg-surface);\n}\n.ao-input.has-error { border-color: var(--danger); }\n.ao-input::placeholder { color: var(--fg-faint, var(--fg-muted)); }\n\n/* Select */\n.ao-select {\n  height: 32px;\n  padding: 0 10px;\n  background: var(--bg-sunken);\n  border: 1px solid var(--border);\n  border-radius: var(--r, 6px);\n  color: var(--fg);\n  font-size: 12.5px;\n  font-family: inherit;\n  width: 100%;\n  box-sizing: border-box;\n  outline: none;\n  cursor: pointer;\n  transition: border-color .1s;\n  appearance: auto;\n}\n.ao-select:focus { border-color: var(--primary); }\n\n/* Checkbox row */\n.ao-form-check {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  margin-bottom: 12px;\n}\n.ao-form-check input[type=\"checkbox\"] {\n  width: 15px;\n  height: 15px;\n  accent-color: var(--primary);\n  cursor: pointer;\n}\n.ao-form-check label {\n  font-size: 12.5px;\n  cursor: pointer;\n}\n\n/* Inline field error */\n.ao-form-err {\n  font-size: 10.5px;\n  color: var(--danger);\n  margin-top: 2px;\n}\n\n/* Submit error banner */\n.ao-form-submit-err {\n  background: color-mix(in srgb, var(--danger) 10%, transparent);\n  border: 1px solid color-mix(in srgb, var(--danger) 40%, transparent);\n  border-radius: var(--r, 6px);\n  padding: 8px 10px;\n  font-size: 12px;\n  color: var(--danger);\n  margin-bottom: 12px;\n}\n\n/* Footer row */\n.ao-form-footer {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n  margin-top: 16px;\n  padding-top: 12px;\n  border-top: 1px solid var(--border-soft);\n}\n.ao-form-footer .ao-form-footer-spacer { flex: 1; }\n\n/* Danger button variant (delete) */\n.ao-btn.v-danger {\n  background: color-mix(in srgb, var(--danger) 12%, transparent);\n  border-color: var(--danger);\n  color: var(--danger);\n}\n.ao-btn.v-danger:hover { opacity: .85; }\n\n/* Outline button variant (cancel) */\n.ao-btn.v-outline {\n  background: transparent;\n  border-color: var(--border);\n  color: var(--fg-muted);\n}\n.ao-btn.v-outline:hover { border-color: var(--fg-muted); color: var(--fg); }\n\n/* Primary button variant (save) */\n.ao-btn.v-primary {\n  background: var(--primary);\n  border-color: var(--primary);\n  color: var(--primary-fg);\n}\n.ao-btn.v-primary:hover { opacity: .9; }\n.ao-btn.v-primary:disabled { opacity: .4; pointer-events: none; }\n\n/* Delete-confirm inline banner inside edit modal */\n.ao-delete-confirm {\n  background: color-mix(in srgb, var(--danger) 8%, transparent);\n  border: 1px solid color-mix(in srgb, var(--danger) 35%, transparent);\n  border-radius: var(--r, 6px);\n  padding: 10px 12px;\n  font-size: 12px;\n  color: var(--danger);\n  margin-top: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.ao-delete-confirm .ao-delete-confirm-btns {\n  display: flex;\n  gap: 8px;\n}\n\n/* ============ LIVE — the Live tail view ============ */\n/* WP-13. Class naming: .ao-live-*. */\n\n/* ============ LIVE SCREEN ============ */\n.ao-live-screen {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow: hidden;\n}\n\n.ao-live-header {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 11px 18px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n.ao-live-header h1 {\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: -.01em;\n  margin: 0;\n}\n.ao-live-header .sub {\n  font-size: 11px;\n  color: var(--fg-muted);\n}\n.ao-live-header .ao-spacer { flex: 1; }\n\n/* ============ JOB PICKER ============ */\n.ao-live-picker {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.ao-live-picker-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  height: 100%;\n  color: var(--fg-muted);\n  font-size: 13px;\n}\n\n.ao-live-job-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 10px 18px;\n  border-bottom: 1px solid var(--border-soft);\n  cursor: pointer;\n  transition: background .1s;\n}\n.ao-live-job-row:hover { background: var(--bg-raised); }\n.ao-live-job-row.is-running { background: color-mix(in srgb, var(--systemic) 6%, transparent); }\n\n.ao-live-job-id {\n  font-family: var(--font-mono);\n  font-size: 12px;\n  color: var(--fg);\n  flex: 1;\n  min-width: 0;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.ao-live-job-id .ns { color: var(--fg-faint, var(--fg-subtle)); }\n\n.ao-live-job-meta {\n  font-size: 11px;\n  color: var(--fg-muted);\n  flex-shrink: 0;\n}\n\n/* ============ CONSOLE AREA ============ */\n.ao-live-body {\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.ao-live-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 14px;\n  border-bottom: 1px solid var(--border-soft);\n  flex-shrink: 0;\n  background: var(--bg-raised);\n}\n.ao-live-toolbar .ao-live-target {\n  font-family: var(--font-mono);\n  font-size: 12px;\n  color: var(--fg);\n  flex: 1;\n  min-width: 0;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.ao-live-toolbar .ao-live-target .ns {\n  color: var(--fg-faint, var(--fg-subtle));\n}\n.ao-live-toolbar .ao-spacer { flex: 1; }\n\n.ao-live-status-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 11px;\n  padding: 2px 8px;\n  border-radius: 99px;\n  font-weight: 600;\n  letter-spacing: .01em;\n}\n.ao-live-status-badge.running {\n  background: color-mix(in srgb, var(--systemic) 14%, transparent);\n  color: var(--systemic);\n}\n.ao-live-status-badge.done {\n  background: color-mix(in srgb, var(--fg-muted) 12%, transparent);\n  color: var(--fg-muted);\n}\n.ao-live-status-badge .dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: currentColor;\n  flex-shrink: 0;\n}\n.ao-live-status-badge.running .dot {\n  animation: ao-live-pulse 1.2s ease-in-out infinite;\n}\n\n@keyframes ao-live-pulse {\n  0%, 100% { opacity: 1; }\n  50% { opacity: .35; }\n}\n\n/* ============ CONSOLE PRE ============ */\n.ao-live-console-wrap {\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n  background: var(--bg-sunken);\n  position: relative;\n}\n\n.ao-live-console {\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  line-height: 1.6;\n  color: var(--fg);\n  white-space: pre-wrap;\n  word-break: break-all;\n  padding: 14px 16px;\n  margin: 0;\n  height: 100%;\n  overflow-y: auto;\n  box-sizing: border-box;\n}\n\n/* ============ AGENT MODE NOTICE ============ */\n.ao-live-agent-notice {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  flex: 1;\n  padding: 32px 24px;\n  text-align: center;\n  color: var(--fg-muted);\n  font-size: 13px;\n  line-height: 1.55;\n}\n.ao-live-agent-notice .notice-title {\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--fg);\n}\n\n/* ============ FINISH BANNER ============ */\n.ao-live-finish-bar {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 14px;\n  background: color-mix(in srgb, var(--systemic) 8%, transparent);\n  border-top: 1px solid color-mix(in srgb, var(--systemic) 20%, transparent);\n  font-size: 12px;\n  color: var(--fg);\n  flex-shrink: 0;\n}\n.ao-live-finish-bar .ao-spacer { flex: 1; }\n.ao-live-finish-bar a {\n  color: var(--primary);\n  text-decoration: none;\n  cursor: pointer;\n  font-weight: 500;\n}\n.ao-live-finish-bar a:hover { text-decoration: underline; }\n\n/* ============ STANDALONE PLACEHOLDER ============ */\n.ao-live-standalone {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  flex: 1;\n  color: var(--fg-muted);\n  font-size: 13px;\n  text-align: center;\n  padding: 24px;\n}\n.ao-live-standalone .console-mock {\n  font-family: var(--font-mono);\n  font-size: 11px;\n  background: var(--bg-sunken);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 12px 16px;\n  width: 320px;\n  max-width: 100%;\n  text-align: left;\n  color: var(--fg-muted);\n  line-height: 1.6;\n  opacity: .7;\n}\n"
